import{ago as agoText,msOf}from"/assets/ago.a1bfba2d21a0.js";import{waited}from"/assets/gpu-reasons.f894b5e314e8.js";export{msOf,waited};export function took(s){if(s==null||!Number.isFinite(s))return"";if(s<9.95)return`${s.toFixed(1)} s`;const t=Math.round(s);if(t<60)return`${t} s`;if(t<3600){const m=Math.floor(t/60);const r=t-m*60;return r?`${m} min ${r} s`:`${m} min`}const mins=Math.round(t/60);const h=Math.floor(mins/60);const m=mins-h*60;return m?`${h} h ${m} min`:`${h} h`}let skew=0;export const now=()=>Date.now()+skew;export function setSkew(asOf){const t=msOf(asOf);if(!Number.isFinite(t))return;const d=t-Date.now();if(Math.abs(d-skew)>1500)skew=d}const items=new Map;let timer=null;function run(){timer=null;if(document.hidden)return;const t=now();for(const[el,it]of items){if(el.isConnected)it.seen=true;else{if(it.seen||Date.now()-it.born>6e4)items.delete(el);continue}const text=it.text(t);if(text!=null&&el.textContent!==text)el.textContent=text}schedule()}function schedule(){if(timer||!items.size||document.hidden)return;timer=setTimeout(run,1005-Date.now()%1e3)}document.addEventListener("visibilitychange",(()=>{if(document.hidden)return;clearTimeout(timer);timer=null;run()}));export function every(el,text){if(!el)return el;items.set(el,{text:text,seen:el.isConnected,born:Date.now()});const first=text(now());if(first!=null&&el.textContent!==first)el.textContent=first;schedule();return el}export function since(el,t0,fmt=took){const a=msOf(t0);return every(el,(t=>Number.isFinite(a)?fmt(Math.max(0,(t-a)/1e3)):""))}export function ago(el,t){return every(el,(n=>agoText(t,n)))}export function stop(el){items.delete(el)}